8	public class ApiException extends RuntimeException {
9	
10	    private final HttpStatus status;
11	    private final String code;
12	
13	    public ApiException(HttpStatus status, String code, String message) {
14	        super(message);
15	        this.status = status;
16	        this.code = code;
17	    }
18	
19	    public HttpStatus status() {
20	        return status;
21	    }
22	
23	    public String code() {
24	        return code;
25	    }
26	
27	    public static ApiException badRequest(String code, String message) {
28	        return new ApiException(HttpStatus.BAD_REQUEST, code, message);
29	    }
30	
31	    public static ApiException notFound(String code, String message) {
32	        return new ApiException(HttpStatus.NOT_FOUND, code, message);
33	    }
