     * 续租。桩实现，后续补全。
     */
    public LeaseView renewLease(long taskId, LeaseRenewRequest request) {
        throw new UnsupportedOperationException();
    }

    /**
     * 租约模式回执。桩实现，后续补全。
     */
    public TaskView leaseReceipt(long taskId, LeaseReceiptRequest request) {
        throw new UnsupportedOperationException();
    }
}

