3	import com.example.starter.firmware.api.LeaseAcquireRequest;
4	import com.example.starter.firmware.api.LeaseRenewRequest;
5	import com.example.starter.firmware.api.LeaseReceiptRequest;
6	import com.example.starter.firmware.api.LeaseView;
7	import com.example.starter.firmware.api.PullResponse;
8	import com.example.starter.firmware.api.ReceiptRequest;
9	import com.example.starter.firmware.api.TaskListResponse;
10	import com.example.starter.firmware.api.TaskView;
11	import com.example.starter.firmware.domain.Device;
12	import com.example.starter.firmware.domain.ReceiptResult;
13	import com.example.starter.firmware.domain.ReleaseOrder;
14	import com.example.starter.firmware.domain.ReleaseStatus;
15	import com.example.starter.firmware.domain.RolloutTask;
16	import com.example.starter.firmware.domain.TaskLease;
17	import com.example.starter.firmware.domain.TaskStatus;
18	import com.example.starter.firmware.error.ApiException;
19	import com.example.starter.firmware.repo.DeviceRepository;
20	import com.example.starter.firmware.repo.LeaseRepository;
21	import com.example.starter.firmware.repo.PauseRecordRepository;
22	import com.example.starter.firmware.repo.ReleaseRepository;
23	import com.example.starter.firmware.repo.TaskRepository;
24	import org.springframework.dao.DuplicateKeyException;
25	import org.springframework.stereotype.Service;
26	
27	import java.time.Clock;
28	import java.time.Instant;
29	import java.util.List;
30	import java.util.Optional;
31	
32	/**
33	 * 投放任务：设备拉取与回执。与取消、恢复并发时统一先锁发布单行，再操作任务，形成一致提交顺序。
34	 * 回执首次终结任务时在发布单行锁内累计当前监控轮次统计，达到阈值即在同一事务原子暂停。
35	 */
36	@Service
37	public class TaskService {
38	
39	    /** 租约有效期：领取或续租时刻起 30 秒，到期时刻左闭右开。 */
40	    static final long LEASE_TTL_SECONDS = 30;
41	
42	    private final TaskRepository taskRepository;
43	    private final ReleaseRepository releaseRepository;
44	    private final DeviceRepository deviceRepository;
45	    private final PauseRecordRepository pauseRecordRepository;
46	    private final LeaseRepository leaseRepository;
47	    private final DeviceService deviceService;
48	    private final ReleaseService releaseService;
49	    private final IdempotencyService idempotency;
50	    private final Clock clock;
51	
52	    public TaskService(TaskRepository taskRepository, ReleaseRepository releaseRepository,
53	                       DeviceRepository deviceRepository, PauseRecordRepository pauseRecordRepository,
54	                       LeaseRepository leaseRepository,
55	                       DeviceService deviceService, ReleaseService releaseService,
56	                       IdempotencyService idempotency, Clock clock) {
57	        this.taskRepository = taskRepository;
58	        this.releaseRepository = releaseRepository;
59	        this.deviceRepository = deviceRepository;
60	        this.pauseRecordRepository = pauseRecordRepository;
61	        this.leaseRepository = leaseRepository;
62	        this.deviceService = deviceService;
63	        this.releaseService = releaseService;
64	        this.idempotency = idempotency;
65	        this.clock = clock;
66	    }
67	
68	    /**
69	     * 设备拉取：已存在任务直接返回；否则仅当型号与当前版本匹配、分桶号小于比例且发布单 ACTIVE 时创建。
70	     * PAUSED 时不创建新任务，已有任务仍可查看与回执。
71	     */
72	    public PullResponse pull(String deviceId, String requestId) {
73	        String fingerprint = String.join("|", "task.pull", deviceId);
74	        return idempotency.execute(requestId, "task.pull", fingerprint, () -> {
75	            Device device = deviceService.findDevice(deviceId);
76	            var activeOrder = releaseRepository.findActiveByModel(device.model());
77	            if (activeOrder.isEmpty()) {
78	                return new PullResponse(null);
79	            }
80	            ReleaseOrder order = releaseRepository.findByIdForUpdate(activeOrder.get().id())
81	                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在"));
82	            var existing = taskRepository.findByReleaseAndDevice(order.id(), deviceId);
83	            if (existing.isPresent()) {
84	                return new PullResponse(TaskView.of(existing.get(), order));
85	            }
86	            if (order.status() != ReleaseStatus.ACTIVE
87	                    || !device.currentVersion().equals(order.fromVersion())
88	                    || device.bucketNo() >= order.ratio()) {
89	                return new PullResponse(null);
90	            }
91	            long taskId;
92	            try {
93	                taskId = taskRepository.insert(order.id(), deviceId);
94	            } catch (DuplicateKeyException e) {
95	                RolloutTask task = taskRepository.findByReleaseAndDevice(order.id(), deviceId)
96	                        .orElseThrow(() -> new IllegalStateException("任务唯一约束冲突后未找到任务"));
97	                return new PullResponse(TaskView.of(task, order));
98	            }
99	            RolloutTask task = taskRepository.findById(taskId)
100	                    .orElseThrow(() -> new IllegalStateException("任务创建后读取失败"));
101	            return new PullResponse(TaskView.of(task, order));
102	        }, PullResponse.class);
103	    }
104	
105	    /**
106	     * 回执：首次回执终结任务并计入完成时所在监控轮次，仅 SUCCESS 更新设备当前版本；
107	     * 同结果重复成功（不重复计数），改结果 409；已取消任务的后到回执 409 且不更新设备版本。
108	     * 样本达到下限且失败率越限时，同事务将仍为 ACTIVE 的发布单原子转为 PAUSED 并落暂停记录。
109	     */
110	    public TaskView receipt(long taskId, ReceiptRequest request) {
111	        String fingerprint = String.join("|", "task.receipt", String.valueOf(taskId), request.result().name());
112	        return idempotency.execute(request.requestId(), "task.receipt", fingerprint, () -> {
113	            RolloutTask snapshot = taskRepository.findById(taskId)
114	                    .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
115	            ReleaseOrder lockedOrder = releaseRepository.findByIdForUpdate(snapshot.releaseId())
116	                    .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在"));
117	            RolloutTask task = taskRepository.findByIdForUpdate(taskId)
118	                    .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
119	            // 已进入租约模式的任务不得再走原回执入口，防止旧代理绕过 agentId/token 校验
120	            if (leaseRepository.findByTaskIdForUpdate(taskId).isPresent()) {
121	                throw ApiException.conflict("LEASE_MODE_REQUIRED",
122	                        "任务已进入租约模式，须携带 agentId 与 token 走租约回执");
123	            }
124	            return switch (task.status()) {
125	                case PENDING -> completePending(task, lockedOrder, request.result());
126	                case SUCCESS, FAILED -> {
127	                    if (task.firstResult() == request.result()) {
128	                        yield TaskView.of(task, lockedOrder);
129	                    }
130	                    throw ApiException.conflict("RECEIPT_RESULT_CONFLICT",
131	                            "任务已终结为 " + task.firstResult() + "，不能改为 " + request.result());
132	                }
133	                case CANCELLED -> throw ApiException.conflict("TASK_CANCELLED", "任务已取消，回执不再受理");
134	            };
135	        }, TaskView.class);
136	    }
137	
138	    /**
139	     * 样本数达到下限且 FAILED×100 >= 样本数×阈值 时，将仍为 ACTIVE 的发布单原子转为 PAUSED。
140	     * 调用方持有发布单行锁，并发回执串行通过，每轮至多生成一条暂停记录。
141	     */
142	    private void pauseIfThresholdReached(ReleaseOrder order, long triggerTaskId) {
143	        if (order.status() != ReleaseStatus.ACTIVE) {
144	            return;
145	        }
146	        int samples = order.roundSuccess() + order.roundFailed();
147	        if (samples < order.sampleFloor()) {
148	            return;
149	        }
150	        if ((long) order.roundFailed() * 100 < (long) samples * order.failureThresholdPercent()) {
151	            return;
152	        }
153	        if (releaseRepository.pauseIfActive(order.id()) == 1) {
154	            pauseRecordRepository.insert(order.id(), order.monitorRound(), triggerTaskId,
155	                    order.roundSuccess(), order.roundFailed(), Instant.now(clock).toString());
156	        }
157	    }
158	
159	    public TaskListResponse listByRelease(long releaseId, TaskStatus statusFilter) {
160	        ReleaseOrder order = releaseService.findOrder(releaseId);
161	        List<TaskView> tasks = taskRepository.findByRelease(releaseId, statusFilter).stream()
162	                .map(task -> TaskView.of(task, order))
163	                .toList();
164	        return new TaskListResponse(tasks);
165	    }
166	
167	    /**
168	     * 领取（或到期接管）执行租约：
169	     * 首次领取得到 token=1 与当前时刻后 30 秒到期；有效期左闭右开，有效租约不能被其他代理抢占；
170	     * 到期后任何代理都可领取新 token（序号加一）；SUCCESS/FAILED 一次终结后不能再领取。
171	     * 本人对自己未到期租约重复领取，返回首次租约快照（幂等展示，不恢复已失效租约的有效性）。
172	     */
173	    public LeaseView acquireLease(long taskId, LeaseAcquireRequest request) {
174	        String fingerprint = String.join("|", "task.lease.acquire", String.valueOf(taskId), request.agentId());
175	        return idempotency.execute(request.requestId(), "task.lease.acquire", fingerprint, () -> {
176	            Instant now = Instant.now(clock);
177	            LockedTask locked = lockTaskAndOrder(taskId);
178	            RolloutTask task = locked.task();
179	            if (task.status() == TaskStatus.CANCELLED) {
180	                throw ApiException.conflict("TASK_CANCELLED", "任务已取消，不能领取租约");
181	            }
182	            Optional<TaskLease> existing = leaseRepository.findByTaskIdForUpdate(taskId);
183	            if (existing.isEmpty()) {
184	                if (task.status() != TaskStatus.PENDING) {
185	                    throw ApiException.conflict("TASK_TERMINATED",
186	                            "任务已一次终结为 " + task.firstResult() + "，不能再领取租约");
187	                }
188	                String expiresAt = now.plusSeconds(LEASE_TTL_SECONDS).toString();
189	                leaseRepository.insert(taskId, request.agentId(), expiresAt);
190	                return LeaseView.of(taskId, leaseRepository.findByTaskIdForUpdate(taskId).orElseThrow());
191	            }
192	            TaskLease lease = existing.get();
193	            if (lease.terminal()) {
194	                throw ApiException.conflict("TASK_TERMINATED",
195	                        "任务已一次终结为 " + task.firstResult() + "，不能再领取租约");
196	            }
197	            if (now.isBefore(Instant.parse(lease.expiresAtUtc()))) {
198	                if (lease.currentAgentId().equals(request.agentId())) {
199	                    // 本人重放：返回首次租约快照，但不改变其到期时刻，即不恢复有效性
200	                    return LeaseView.of(taskId, lease);
201	                }
202	                throw ApiException.conflict("LEASE_HELD_BY_OTHER",
203	                        "租约在有效期内，当前持有人: " + lease.currentAgentId());
204	            }
205	            // 到期接管：令牌加一，原 token 即刻失效
206	            String expiresAt = now.plusSeconds(LEASE_TTL_SECONDS).toString();
207	            if (leaseRepository.takeOverExpired(taskId, request.agentId(), expiresAt) != 1) {
208	                throw ApiException.conflict("TASK_TERMINATED", "任务已终结，不能接管租约");
209	            }
210	            return LeaseView.of(taskId, leaseRepository.findByTaskIdForUpdate(taskId).orElseThrow());
211	        }, LeaseView.class);
212	    }
213	
214	    /**
215	     * 续租：须本人（agentId）凭当前 token 且租约未到期，期限改为当前时刻后 30 秒。
216	     * CANCELLED 任务或已终结租约不允许续租；到期、旧代理或非持有人均 409。
217	     */
218	    public LeaseView renewLease(long taskId, LeaseRenewRequest request) {
219	        String fingerprint = String.join("|", "task.lease.renew", String.valueOf(taskId),
220	                request.agentId(), String.valueOf(request.token()));
221	        return idempotency.execute(request.requestId(), "task.lease.renew", fingerprint, () -> {
222	            Instant now = Instant.now(clock);
223	            LockedTask locked = lockTaskAndOrder(taskId);
224	            TaskLease lease = leaseRepository.findByTaskIdForUpdate(taskId)
225	                    .orElseThrow(() -> ApiException.conflict("LEASE_NOT_FOUND", "任务尚未领取租约，不能续租"));
226	            if (locked.task().status() == TaskStatus.CANCELLED || lease.terminal()) {
227	                throw ApiException.conflict("LEASE_NOT_RENEWABLE", "任务已终结或已取消，不能续租");
228	            }
229	            if (!lease.currentAgentId().equals(request.agentId()) || lease.currentToken() != request.token()) {
230	                throw ApiException.conflict("LEASE_NOT_HELD_BY_CALLER",
231	                        "续租须由当前持有人凭当前 token 申请");
232	            }
233	            if (!now.isBefore(Instant.parse(lease.expiresAtUtc()))) {
234	                throw ApiException.conflict("LEASE_EXPIRED", "租约已到期，不能续租，请重新领取");
235	            }
236	            String expiresAt = now.plusSeconds(LEASE_TTL_SECONDS).toString();
237	            leaseRepository.renew(taskId, request.agentId(), request.token(), expiresAt);
238	            return LeaseView.of(taskId, leaseRepository.findByTaskIdForUpdate(taskId).orElseThrow());
239	        }, LeaseView.class);
240	    }
241	
242	    /**
243	     * 租约模式回执：必须携带 agentId 与 token。到期、旧代理（token 已被接管）或非持有人一律 409，
244	     * 且不改动设备版本与监控统计。SUCCESS/FAILED 一次终结，冻结实际代理与 token；
245	     * 同一 token 的终结至多发生一次，仅首次终结计入监控样本。原暂停规则保持：既有任务回执不受影响。
246	     */
247	    public TaskView leaseReceipt(long taskId, LeaseReceiptRequest request) {
248	        String fingerprint = String.join("|", "task.lease.receipt", String.valueOf(taskId),
249	                request.agentId(), String.valueOf(request.token()), request.result().name());
250	        return idempotency.execute(request.requestId(), "task.lease.receipt", fingerprint, () -> {
251	            Instant now = Instant.now(clock);
252	            LockedTask locked = lockTaskAndOrder(taskId);
253	            TaskLease lease = leaseRepository.findByTaskIdForUpdate(taskId)
254	                    .orElseThrow(() -> ApiException.conflict("LEASE_NOT_FOUND", "任务尚未领取租约"));
255	            boolean holder = lease.currentAgentId().equals(request.agentId())
256	                    && lease.currentToken() == request.token()
257	                    && !lease.terminal()
258	                    && now.isBefore(Instant.parse(lease.expiresAtUtc()));
259	            if (!holder) {
260	                throw ApiException.conflict("LEASE_INVALID",
261	                        "租约无效、已到期或不属于该代理，回执被拒绝，设备与统计不变");
262	            }
263	            RolloutTask task = locked.task();
264	            return switch (task.status()) {
265	                case PENDING -> {
266	                    TaskView view = completePending(task, locked.order(), request.result());
267	                    leaseRepository.markTerminal(taskId, request.agentId(), request.token());
268	                    yield view;
269	                }
270	                case SUCCESS, FAILED -> {
271	                    // 首次终结已冻结实际代理与 token；非首次回执一律拒绝，同一 token 终结至多一次
272	                    throw ApiException.conflict("TASK_TERMINATED",
273	                            "任务已终结为 " + task.firstResult() + "，不能再次回执");
274	                }
275	                case CANCELLED -> throw ApiException.conflict("TASK_CANCELLED", "任务已取消，回执不再受理");
276	            };
277	        }, TaskView.class);
278	    }
279	
280	    /**
281	     * 查询租约当前快照（只读，不自动领取、不延期）。未进入租约模式的任务 409。
282	     */
283	    public LeaseView getLease(long taskId) {
284	        taskRepository.findById(taskId)
285	                .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
286	        TaskLease lease = leaseRepository.findByTaskId(taskId)
287	                .orElseThrow(() -> ApiException.conflict("LEASE_NOT_FOUND", "任务尚未领取租约"));
288	        return LeaseView.of(taskId, lease);
289	    }
290	
291	    /**
292	     * 统一加锁顺序：先发布单行锁，再任务行锁，使接管、回执、取消、续租串行校验、提交顺序一致。
293	     */
294	    private LockedTask lockTaskAndOrder(long taskId) {
295	        RolloutTask snapshot = taskRepository.findById(taskId)
296	                .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
297	        ReleaseOrder order = releaseRepository.findByIdForUpdate(snapshot.releaseId())
298	                .orElseThrow(() -> ApiException.notFound("RELEASE_NOT_FOUND", "发布单不存在"));
299	        RolloutTask task = taskRepository.findByIdForUpdate(taskId)
300	                .orElseThrow(() -> ApiException.notFound("TASK_NOT_FOUND", "任务不存在: " + taskId));
301	        return new LockedTask(task, order);
302	    }
303	
304	    /**
305	     * 首次终结任务：置任务终态、累计当前监控轮次统计、成功时更新设备版本、必要时同事务暂停。
306	     * 仅在任务为 PENDING 时调用，调用方持有发布单与任务行锁，保证同一任务至多首次终结计样本。
307	     */
308	    private TaskView completePending(RolloutTask task, ReleaseOrder lockedOrder, ReceiptResult result) {
309	        taskRepository.complete(task.id(), result);
310	        releaseRepository.incrementRoundStats(task.releaseId(), result);
311	        if (result == ReceiptResult.SUCCESS) {
312	            deviceRepository.updateCurrentVersion(task.deviceId(), lockedOrder.toVersion());
313	        }
314	        ReleaseOrder updated = releaseRepository.findById(task.releaseId()).orElseThrow();
315	        pauseIfThresholdReached(updated, task.id());
316	        return TaskView.of(taskRepository.findById(task.id()).orElseThrow(), updated);
317	    }
318	
319	    private record LockedTask(RolloutTask task, ReleaseOrder order) {
320	    }
321	}
